package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealMatrix constructor.
 */
public class OpenMapRealMatrix_OpenMapRealMatrix_TriageGen1Test {









    @Test
    public void testConstructorFunctionality() {
        int rows = 3;
        int cols = 3;
        OpenMapRealMatrix matrix = new OpenMapRealMatrix(rows, cols);

        // Test that entries are initialized to 0.0 (default for sparse matrix)
        matrix.setEntry(1, 1, 5.5);
        assertEquals("Value at (1,1) should be 5.5", 5.5, matrix.getEntry(1, 1), 1e-10);
        assertEquals("Value at (0,0) should be 0.0", 0.0, matrix.getEntry(0, 0), 1e-10);
    }


}

package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealMatrix constructor.
 */
public class OpenMapRealMatrix_OpenMapRealMatrix_TriageGen1Test {











    @Test
    public void testCopyConstructor() {
        int rows = 2;
        int cols = 2;
        OpenMapRealMatrix original = new OpenMapRealMatrix(rows, cols);
        original.setEntry(0, 0, 1.0);
        original.setEntry(1, 1, 2.0);

        OpenMapRealMatrix copy = new OpenMapRealMatrix(original);

        assertNotNull("Copy should not be null", copy);
        assertEquals("Rows should match", original.getRowDimension(), copy.getRowDimension());
        assertEquals("Cols should match", original.getColumnDimension(), copy.getColumnDimension());
        assertEquals("Entry (0,0) should match", original.getEntry(0, 0), copy.getEntry(0, 0), 1e-10);
        assertEquals("Entry (1,1) should match", original.getEntry(1, 1), copy.getEntry(1, 1), 1e-10);

        // Ensure it is a deep copy
        copy.setEntry(0, 0, 9.9);
        assertNotEquals("Copy should not affect original", original.getEntry(0, 0), copy.getEntry(0, 0), 1e-10);
    }
}
